CREATE TABLE IF NOT EXISTS maintenance_requests(
 id TEXT PRIMARY KEY,installation TEXT NOT NULL,administrator TEXT NOT NULL,revision INTEGER NOT NULL,
 from_build TEXT NOT NULL,manifest_digest TEXT NOT NULL,version TEXT NOT NULL,
 public_key TEXT NOT NULL,secret_backup TEXT NOT NULL,created INTEGER NOT NULL,expires INTEGER NOT NULL,
 revoked INTEGER,phase TEXT NOT NULL DEFAULT 'approved',message TEXT NOT NULL DEFAULT '',
 backup_digest TEXT,backup_file TEXT,previous_version TEXT,target_version TEXT
);
CREATE TABLE IF NOT EXISTS maintenance_lock(
 id INTEGER PRIMARY KEY CHECK(id=1),request TEXT NOT NULL,created INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS maintenance_history(
 id INTEGER PRIMARY KEY AUTOINCREMENT,request TEXT NOT NULL,actor TEXT NOT NULL,
 event TEXT NOT NULL,created INTEGER NOT NULL
);

-- Atomic write barrier: requests already running cannot commit after the lock.
CREATE TRIGGER IF NOT EXISTS maintenance_staff_accounts_insert BEFORE INSERT ON staff_accounts WHEN EXISTS(SELECT 1 FROM maintenance_lock WHERE id=1) BEGIN SELECT RAISE(ABORT,'LT360_MAINTENANCE'); END;
CREATE TRIGGER IF NOT EXISTS maintenance_staff_accounts_update BEFORE UPDATE ON staff_accounts WHEN EXISTS(SELECT 1 FROM maintenance_lock WHERE id=1) BEGIN SELECT RAISE(ABORT,'LT360_MAINTENANCE'); END;
CREATE TRIGGER IF NOT EXISTS maintenance_staff_accounts_delete BEFORE DELETE ON staff_accounts WHEN EXISTS(SELECT 1 FROM maintenance_lock WHERE id=1) BEGIN SELECT RAISE(ABORT,'LT360_MAINTENANCE'); END;
